const save=async()=>{await writeFile(arquivo,JSON.stringify(f,null,2)+'\n');rel.resultados=[...r.values()];rel.data=new Date().toISOString();await writeFile(saida,JSON.stringify(rel,null,2)+'\n');};
const dia=(n:number)=>{const d=new Date(f.dataBase+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
let token='';
async function req(path:string,method='GET',body?:unknown,sitio:number|null=q.sitio?.id,cred=token){const init:RequestInit={method,headers:{'content-type':'application/json',...(cred?{authorization:'Bearer '+cred}:{}),...(sitio?{'X-Propriedade-Id':String(sitio)}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})};let response:Response|undefined;for(let tentativa=0;tentativa<5;tentativa++){try{response=await fetch(base+path,init);break;}catch(e){if(tentativa===4||!JSON.stringify((e as Error&{cause?:unknown}).cause).includes('ECONNREFUSED'))throw e;await new Promise(r=>setTimeout(r,400));}}assert(response);const text=await response.text();let data;try{data=JSON.parse(text);}catch{data={error:text.slice(0,200)};}return{status:response.status,data};}
function bom(v:{status:number;data:any}){assert(v.status<300,`Esperado2xx: ${v.status} ${JSON.stringify(v.data)}`);return v.data;}
function ruim(v:{status:number;data:any}){assert(v.status>=400&&v.status<500,`Esperado4xx: ${v.status} ${JSON.stringify(v.data)}`);return v.data;}
const ap=async(path:string,method='GET',body?:unknown,sitio:number|null=q.sitio?.id)=>bom(await req(path,method,body,sitio));
async function chave(k:string){if(!q.chaves[k]){q.chaves[k]=randomUUID();await save();}return q.chaves[k];}
async function once(k:string,fn:()=>Promise<any>){if(!q.dados[k]){q.dados[k]=await fn();await save();}return q.dados[k];}
async function caso(id:string,fn:()=>Promise<string>,modo='HTTP real + conferência PostgreSQL'){if(r.get(id)?.status==='passed'&&id!=='FU-ENV-05')return;const inicio=Date.now(),anterior=r.get(id);try{const detalhe=await fn();r.set(id,{id,status:'passed',modo,detalhe,data:new Date().toISOString(),duracaoMs:Date.now()-inicio,...(anterior?{evidenciaAnterior:anterior}:{})});}catch(e){r.set(id,{id,status:'failed',modo,detalhe:e instanceof Error?e.message:String(e),data:new Date().toISOString(),duracaoMs:Date.now()-inicio,...(anterior?{evidenciaAnterior:anterior}:{})});}await save();const v=r.get(id);console.log(JSON.stringify({id,status:v.status,detalhe:v.detalhe}));}
const produto=(k:string,rastrearPartidas=false)=>once(k,()=>ap('/estoque/produtos','POST',{nome:q.execucao+' · '+k,unidade:'UN',categoriaId:f.categoriaId,centroCustoIds:[f.centroCustoId],rastrearPartidas}));
