const aplicacao=async(k:string,a:any,data=dia(-20))=>once(k,async()=>ap(root+'/sanidade/aplicacoes','POST',{chave:await chave(k),animalId:a.id,propriedadeId:q.sitio.id,data,nomeProdutoAplicado:q.execucao+' preparo '+k,origemInsumo:'SEM_ORIGEM_JUSTIFICADA',dose:'1',unidadeDose:'ML',justificativaSemOrigem:'QA322R material documentado fictício sem consumo do seed',estadoCarenciaLeite:'NAO_APLICAVEL',estadoCarenciaCarne:'NAO_APLICAVEL',justificativaCarenciaLeite:'QA322R insumo fictício, sem indicação clínica',justificativaCarenciaCarne:'QA322R insumo fictício, sem indicação clínica'}));
async function classe(k:string,tipo:string,id:string,extra:Record<string,unknown>={}){return once(k,async()=>{const param=({APLICACAO:'aplicacaoId',TENTATIVA:'tentativaId',EXAME:'exameId',NUTRICAO:'animalId'} as Record<string,string>)[tipo];const d=await ap(root+'/custos?'+param+'='+id);const versao=d.fontes.find((f:any)=>f.id===id)?.versaoClassificacao??0;return ap(root+'/custos/classificacao','PUT',{chave:await chave(k),propriedadeId:q.sitio.id,tipo,fonteId:id,versao,motivo:q.execucao+' classificação conferida',finalidade:'REPRODUCAO',materialNaoAplicavel:false,servicoNaoAplicavel:true,coberturaServico:'PROCEDIMENTO',materialDocumentado:{valor:'30.00',referencia:'QA322R documento',evidencia:'Valor fictício comprovado pela fixture'},...extra});});}
const vinculo=async(k:string,t:any,a:any,modo='PARCELA',valorMaterial?:string)=>once(k,async()=>ap(root+'/custos/preparatorios','POST',{chave:await chave(k),propriedadeId:q.sitio.id,tentativaId:t.id,tipo:'APLICACAO',fonteId:a.id,modo,motivo:q.execucao+' vínculo explícito',...(valorMaterial===undefined?{}:{valorMaterial})}));
async function legadoEstoque(k:string,p:any,quantidade:number,data=dia(-20)){return once(k,async()=>{assert(p.nome.startsWith('QA322R-'));const id=await chave(k);return prisma.$transaction(async tx=>{const existente=await tx.movimentoEstoque.findUnique({where:{id}});if(existente)return existente;const m=await tx.movimentoEstoque.create({data:{id,produtoId:p.id,propriedadeId:q.sitio.id,tipo:'ENTRADA',origem:'INVENTARIO_INICIAL',data:new Date(data),quantidade,custoUnitario:0,valorTotal:0,metodoValorizacao:'LEGADO',criadoPorId:1,observacao:'QA322R fixture histórica sem comprovação monetária; zero armazenado não é lastro conhecido'}});await auditar(tx,{entidade:'FixtureQALegado',entidadeId:m.id,acao:'PREPARACAO_QA322',usuarioId:1,motivo:'Reproduzir saldo histórico desconhecido somente em produto QA322R',depois:{produtoId:p.id,propriedadeId:q.sitio.id,quantidade,metodo:'LEGADO'}});return m;});});}
