async function programa(k:string,a:any,protocolo:any,inicio:string){const p=await once(k,async()=>ap(rep+'/programacoes','POST',{chave:await chave(k),propriedadeId:q.sitio.id,protocoloId:protocolo.id,nome:q.execucao+' '+k,inicioPrevisto:inicio,animais:[{animalId:a.id}]}));let detalhe=await ap(rep+'/programacoes/'+p.id);const part=detalhe.participantes.find((p:any)=>p.animalId===a.id);await once(k+'-inicio',()=>ap(rep+'/participantes-iatf/'+part.id+'/inicio','POST',{propriedadeId:q.sitio.id,inicioEfetivo:inicio}));detalhe=await ap(rep+'/programacoes/'+p.id);return{programa:p,participante:detalhe.participantes.find((p:any)=>p.id===part.id)};}
