async function fingerprint(){const manifesto=JSON.parse(await readFile('.seedatev3/manifesto.json','utf8'));const ids=Object.values(manifesto.ids).filter((v):v is string=>typeof v==='string'&&/^[a-f\d-]{36}$/i.test(v));const linhas=[];for(const m of Prisma.dmmf.datamodel.models){const campo=m.fields.find(f=>f.name==='id');if(campo?.type!=='String'||!campo.isId||m.name==='Sessao')continue;const db=(prisma as any)[m.name[0].toLowerCase()+m.name.slice(1)];if(!db)continue;const rows=await db.findMany({where:{id:{in:ids}},orderBy:{id:'asc'}});if(rows.length)linhas.push({modelo:m.name,linhas:rows.length,sha256:createHash('sha256').update(JSON.stringify(rows)).digest('hex')});}return linhas;}
