  await caso('FU-CUS-11',async()=>{for(const extra of [{valorMaterial:'0.01'},{}])ruim(await req(root+'/custos/preparatorios','POST',{chave:randomUUID(),propriedadeId:q.sitio.id,tentativaId:t3.id,tipo:'APLICACAO',fonteId:parcelado.id,modo:'PARCELA',motivo:'QA322R excesso/parcela ausente',...extra}));assert.equal(await prisma.vinculoPreparoTentativa.count({where:{aplicacaoId:parcelado.id}}),2);return 'Excesso30,01 e parcela sem valores recusados; dois vínculos válidos preservados.';});
  await caso('FU-CUS-12',async()=>{const outro=await animal('outroCusto'),posterior=await aplicacao('preparoPosterior',a,dia(-1)),deOutro=await aplicacao('preparoOutro',outro);for(const p of [posterior,deOutro])ruim(await req(root+'/custos/preparatorios','POST',{chave:randomUUID(),propriedadeId:q.sitio.id,tentativaId:t3.id,tipo:'APLICACAO',fonteId:p.id,modo:'INTEGRAL',motivo:'QA322R cronologia/animal incompatível'}));return 'Preparatório posterior e preparatório de outro animal recusados antes de criar vínculo.';});
  await caso('FU-SEG-08',async()=>{const b={propriedadeId:q.sitio.id,tipo:'APLICACAO',fonteId:disputa.id,modo:'PARCELA',valorMaterial:'20.00',motivo:'QA322R disputa da origem30'};const rs=await Promise.all([req(root+'/custos/preparatorios','POST',{...b,chave:await chave('disputa1'),tentativaId:t1.id}),req(root+'/custos/preparatorios','POST',{...b,chave:await chave('disputa2'),tentativaId:t2.id})]);assert.equal(rs.filter(r=>r.status<300).length,1);assert.equal(rs.filter(r=>r.status===409).length,1);assert.equal((await prisma.vinculoPreparoTentativa.aggregate({where:{aplicacaoId:disputa.id,encerradoEm:null},_sum:{valorMaterial:true}}))._sum.valorMaterial?.toFixed(2),'20.00');return 'Completa o ensaio anterior de saldo: disputa concorrente20+20 da origem30 aceita só uma atribuição; soma20, sem excesso.';});
  await caso('FU-CUS-13',async()=>{const v=q.dados.vIntegral;await once('encerraIntegral',async()=>ap(root+'/custos/preparatorios/'+v.id+'/encerramento','POST',{chave:await chave('encerraIntegral'),propriedadeId:q.sitio.id,motivo:'QA322R atribuição encerrada com histórico'}));const atual=await prisma.vinculoPreparoTentativa.findUniqueOrThrow({where:{id:v.id}});assert(atual.encerradoEm&&atual.motivoEncerramento);assert(await prisma.aplicacaoProduto.findUnique({where:{id:integral.id}}));await vinculo('integralReatribuida',t2,integral,'INTEGRAL');assert.equal(await prisma.vinculoPreparoTentativa.count({where:{aplicacaoId:integral.id}}),2);return 'Encerramento preservou original e motivo, liberou capacidade e permitiu novo vínculo sem inverso de estoque.';});
