  await caso('FU-TEM-06',async()=>{const a=await animal('temporal-atraso');await inicial('inicialTemp-atraso',a,dia(-80));const p=await programa('programaTemp-atraso',a,prot,dia(-50)+'T08:00:00-03:00'),ts=p.participante.tarefas,before=ts.filter((t:any)=>t.etapa>0).map((t:any)=>[t.id,t.previstaEm]);await executar('execTemp-atraso',ts.find((t:any)=>t.etapa===0),dia(-48)+'T08:00:00-03:00');const after=await ap(rep+'/programacoes/'+p.programa.id);assert.deepEqual(after.participantes[0].tarefas.filter((t:any)=>t.etapa>0).map((t:any)=>[t.id,t.previstaEm]),before);return 'Executar primeira etapa com24h de atraso conserva todas as previsões das etapas seguintes; nenhum deslocamento silencioso.';});
